:root {
  /* Tipografía */
  --prep-font-family: "Segoe UI", Arial, sans-serif;
  --prep-number-font: "IBM Plex Mono", Consolas, monospace;

  /* Textos */
  --prep-text-primary: #000000;
  --prep-text-secondary: #000000;

  /* Cuerda */
  --prep-fiber-color: #0A638F;

  /* Poleas */
  --prep-roller-fill: #D7D8DB;
  --prep-roller-border: #4E4E4E;
  --prep-roller-number: #000000;

  /* Cubas */
  --prep-tank-fill: #D7D8DB;
  --prep-tank-liquid: #A0CFE9;
  --prep-tank-border: #223151;

  /* Tuberías */
  --prep-steam-color: #930606;
  --prep-condensate-color: #4E4E4E;

  /* Control */
  --prep-control-color: #01524F;

  /* Válvulas */
  --prep-valve-color: #0E0E55;

  /* Grosores */
  --prep-fiber-width: 2.8px;
  --prep-roller-border-width: 2.2px;
  --prep-process-width: 1.6px;
  --prep-process-main-width: 2px;
  --prep-control-width: 1.6px;
  --prep-tank-border-width: 1.4px;
  --prep-valve-width: 1.4px;

  /* Numeración */
  --prep-roller-number-size: 13px;
}

/* ==========================================================
   ENTORNO TRANSPARENTE
   ========================================================== */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.prep-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--prep-font-family);
  pointer-events: none;
}

.prep-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

/* Representación completamente estática */
.prep-widget,
.prep-widget * {
  animation: none !important;
  transition: none !important;
}

/* ==========================================================
   COLORES BASE DE LOS DEGRADADOS
   ========================================================== */

.roller-metal-base {
  stop-color: var(--prep-roller-fill);
}

.tank-metal-base {
  stop-color: var(--prep-tank-fill);
}

.tank-liquid-base {
  stop-color: var(--prep-tank-liquid);
}

/* ==========================================================
   CUBAS: METAL SATINADO
   ========================================================== */

.tank-group {
  filter: url("#prep4-tank-shadow");
}

.tank-upper {
  fill: url("#prep4-tank-metal");
  stroke: none;
}

.tank-lower {
  fill: url("#prep4-liquid-gradient");
  stroke: none;
  filter: url("#prep4-liquid-inset");
}

.tank-outline {
  fill: none;
  stroke: var(--prep-tank-border);
  stroke-width: var(--prep-tank-border-width);
  stroke-linejoin: round;
}

.tank-top-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  opacity: 0.48;
}

.tank-bottom-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.65px;
  stroke-linecap: round;
  opacity: 0.14;
}

/* ==========================================================
   CUERDAS
   ========================================================== */

.fiber {
  fill: none;
  stroke: var(--prep-fiber-color);
  stroke-width: var(--prep-fiber-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* ==========================================================
   POLEAS: METAL SATINADO SIN ANILLO INTERIOR
   ========================================================== */

.roller-body {
  fill: url("#prep4-roller-metal");
  stroke: var(--prep-roller-border);
  stroke-width: var(--prep-roller-border-width);
  filter: url("#prep4-roller-shadow");
}

.roller-label {
  fill: var(--prep-roller-number);
  font-family: var(--prep-number-font);
  font-size: var(--prep-roller-number-size);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

/* ==========================================================
   TUBERÍAS CONTINUAS
   ========================================================== */

.steam-line,
.condensate-line,
.control-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.steam-line {
  stroke: var(--prep-steam-color);
  stroke-width: var(--prep-process-width);
}

.condensate-line {
  stroke: var(--prep-condensate-color);
  stroke-width: var(--prep-process-width);
}

.steam-main,
.condensate-main {
  stroke-width: var(--prep-process-main-width);
}

/*
 * Los extremos terminan exactamente en los bordes de las
 * válvulas, sin prolongar el trazo hacia su interior.
 */
.valve-connection {
  stroke-linecap: butt;
}

/* ==========================================================
   CONTROL
   ========================================================== */

.control-line {
  stroke: var(--prep-control-color);
  stroke-width: var(--prep-control-width);
}

.control-node {
  fill: var(--prep-control-color);
  stroke: var(--prep-control-color);
  stroke-width: 1px;
}

/* ==========================================================
   VÁLVULAS TRANSPARENTES
   ========================================================== */

.valve-body {
  fill: none;
  stroke: var(--prep-valve-color);
  stroke-width: var(--prep-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.valve-dot {
  fill: var(--prep-valve-color);
  stroke: var(--prep-valve-color);
  stroke-width: 1px;
}

/* Unión horizontal entre la válvula y su actuador */
.valve-link {
  fill: none;
  stroke: var(--prep-valve-color);
  stroke-width: 0.7px;
  stroke-linecap: round;
}

/* ==========================================================
   TEXTOS
   ========================================================== */

.labels text {
  font-family: var(--prep-font-family);
}

.text-steam {
  fill: var(--prep-steam-color);
  font-size: 12px;
  font-weight: 600;
}

.text-condensate {
  fill: var(--prep-condensate-color);
  font-size: 12px;
  font-weight: 600;
}

.text-footer {
  fill: var(--prep-text-secondary);
  font-size: 17px;
  font-style: italic;
  font-weight: 500;
}
